INSERT INTO `sys_oper_log` VALUES (192, '用户管理', 2, 'com.ruoyi.web.controller.system.SysUserController.edit()', 'PUT', 1, 'admin', NULL, '/system/user', '127.0.0.1', '内网IP', '{\"roles\":[{\"flag\":false,\"roleId\":2,\"admin\":false,\"dataScope\":\"2\",\"params\":{},\"roleSort\":\"2\",\"deptCheckStrictly\":false,\"menuCheckStrictly\":false,\"roleKey\":\"common\",\"roleName\":\"普通角色\",\"status\":\"0\"}],\"phonenumber\":\"15666666666\",\"admin\":false,\"remark\":\"测试员\",\"delFlag\":\"0\",\"password\":\"\",\"updateBy\":\"admin\",\"postIds\":[2],\"loginIp\":\"\",\"email\":\"ry1@qq.com\",\"nickName\":\"若依1\",\"sex\":\"1\",\"deptId\":105,\"avatar\":\"\",\"dept\":{\"deptName\":\"测试部门\",\"leader\":\"若依\",\"deptId\":105,\"orderNum\":\"3\",\"params\":{},\"parentId\":101,\"children\":[],\"status\":\"0\"},\"params\":{},\"userName\":\"若依1\",\"userId\":3,\"createBy\":\"admin\",\"roleIds\":[2],\"createTime\":1788870729000,\"status\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-09-06 20:44:56');
INSERT INTO `sys_oper_log` VALUES (193, '参数管理', 9, 'com.ruoyi.web.controller.system.SysConfigController.refreshCache()', 'DELETE', 1, 'admin', NULL, '/system/config/refreshCache', '127.0.0.1', '内网IP', '{}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-09-06 20:45:22');
INSERT INTO `sys_oper_log` VALUES (194, '文章管理', 2, 'com.ruoyi.cms.blog.controller.CmsBlogController.edit()', 'PUT', 1, 'admin', NULL, '/cms/blog', '127.0.0.1', '内网IP', '{\"tagIds\":[],\"title\":\"啊调查啊\",\"type\":\"2\",\"content\":\"<p>近期做需求中有一些感想，在这里记录下。</p><p><br></p><p><br></p><h2>1. 产品究竟是谁的</h2><p><br></p><p>人人都是产品经理，并不是一句口号，每个人都是用户，即便你是研发、设计、测试，都有无数的时间，和世界上最优秀的产品打交道。最优秀的产品包括你的电脑、手机，和那些最流行的APP。</p><p><br></p><p><br></p><p>所以，如果某个产品经理一言堂，那这个产品大概率不会太成功。除非他真的厉害，并且有数据支撑，比如乔布斯这种。产品不是政治，产品是可以讨论的。</p><p><br></p><p><br></p><p>如果一些交互设计难以理解，研发都用着费劲，怎么在普通人中推广呢？</p><p><br></p><p><br></p><p>另一个问题，研发需要了解并思考产品的逻辑吗？</p><p><br></p><p><br></p><p>答案肯定是需要的，产品是有逻辑的，研发可以根据产品的逻辑，判断、预测未来的变化，抽出稳定性更强的代码。</p><p><br></p><p><br></p><p>一个工作3年和工作10年的研发的一个区别就在于，对于产品逻辑的理解，大概工作更久的人更容易预测产品未来的变化，会在代码编写、结构设计时就拆分出不变与变化，从而让代码更易维护。但是，如果每次新来一个需求，都从0开始，从不思考，就另当别论了。</p><p><br></p><p><br></p><h2>2. 定制与通用</h2><p><br></p><p>通用和定制往往是对立的，一个需求如果是定制的，意味着不够通用。</p><p><br></p><p><br></p><p>前一阵做了一个国际化的需求，国际化其实就代表通用，本地化代表定制。</p><p><br></p><p><br></p><p>但是如果同一类型定制的多了，就可以变为通用需求。本质上一个<code>string/number/boolean</code>类型总是可以扩展成<code>array</code>的。</p><p><br></p><p><br></p><p>比如H5的自动化测试报告处理，和小程序的处理，是可以通用化的。</p><p><br></p><p><br></p><p>这给我们一个启示是，要多沉淀东西，做过的那么多需求，比如表单系统、权限系统，这些工作即使一两年内不会重复，但是时间拉长来，总会在职业生涯的某个阶段重新做一次。</p><p><br></p><p><br></p><p>还有，我们加班那么多，是不是产品设计、需求提出、技术实现的时候，通用性考虑的就不足呢，所以今天在A上拧一个螺丝，明天在B上拧一个螺丝。</p><p><br></p><p><br></p><p>可怕的是，这两个螺丝都是一样的残次品。</p><p><br></p><p><br></p><p>通用性在不同的层次上有不同的表现，比如总监可以考虑业务的通用，产品经理考虑产品的通用，开发则考虑代码和系统层面的。</p><p><br></p><p><br></p><p>组件化的基础也是通用性，如果一个组件可以被复用，说明它是通用的。</p><p><br></p><p><br></p><h2>3. 复用性</h2><p><br></p><p>应当努力追求高复用，不论是组件，还是工具，为什么呢？</p><p><br></p><p><br></p><ol><li><br></li><li>从零实现成本高</li><li><br></li><li><br></li><li>复制粘贴然后改一点，看似成本也不高，后续维护、迭代更新则成本高</li><li><br></li></ol><p><br></p><p>实践证明，组件、工具的迭代更新的频率，一般是高于认知的。即便你当下觉得它很稳定了、很完美了，也很有可能在未来某个时候优化，因为<strong>人的认识总是有局限性的</strong>。</p><p><br></p><p><br></p><p>组件高复用，可以统一升级、统一优化、统一迭代。不同维度的组织都应该追求高复用，包括个人、项目、团队。</p><p><br></p><p><br></p><h2>4. 字段名</h2><p><br></p><p>发现一个现象，大家在字段命名的时候比较洒脱。</p><p><br></p><p><br></p><ul><li><br></li><li>格式比较多样，比如角色Id：<code>roleId</code>、<code>role_id</code>、<code>roleid</code>，子活动Id：', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-09-06 20:54:01');
