 parameters\r\n### SQL: update cms_blog          SET create_by = ?,             create_time = ?,             update_by = ?,             update_time = ?,             title = ?,             type = ?,             content = ?,             content_type = ?,                          Top = ?,             views = ?,             status = ?,             blog_pic_type = ?,             blog_pic = ?,             blog_pic_link = ?,             blog_desc = ?,             blog_files = ?          where id = ?\r\n### Cause: com.mysql.cj.jdbc.exceptions.MysqlDataTruncation: Data truncation: Data too long for column \'blog_pic_link\' at row 1\n; Data truncation: Data too long for column \'blog_pic_link\' at row 1; nested exception is com.mysql.cj.jdbc.exceptions.MysqlDataTruncation: Data truncation: Data too long for column \'blog_pic_link\' at row 1', '2026-09-06 21:07:16');
INSERT INTO `sys_oper_log` VALUES (215, '文章管理', 2, 'com.ruoyi.cms.blog.controller.CmsBlogController.edit()', 'PUT', 1, 'admin', NULL, '/cms/blog', '127.0.0.1', '内网IP', '{\"tagIds\":[25,23],\"title\":\"java入门教程\",\"type\":\"1\",\"content\":\"<p>程序员面试背八股，可以说是现在互联网开发岗招聘不可逆的形式了，其中最卷的当属Java！（网上动不动就是成千上百道的面试题总结）你要是都能啃下来，平时技术不是太差的话，面试基本上问题就不会太大。</p><p><br></p><p><br></p><p>这时候尴尬的现象就出现了：<strong>虽然八股文背的好并不能代表这个人有实际工作能力，但企业还是会坚持要用八股文来考察候选人。</strong> 其中最直接的原因就是国内的开发岗位供过于求，非常内卷，而八股文就是目前企业最高效的甄别候选人的方式。我们无法改变这一现状，所以只能改变自己，适应目前互联网背八股的现状。</p><p><br></p><p>作者：Java水解</p><p>链接：https://juejin.cn/post/7254171813118001209</p><p>来源：稀土掘金</p><h1 class=\\\"ql-align-center\\\"><br></h1>\",\"top\":\"1\",\"updateBy\":\"admin\",\"blogDesc\":\"置顶文章\",\"id\":7,\"contentType\":\"1\",\"views\":80,\"blogFiles\":\"[]\",\"blogPicLink\":\"\",\"types\":[{\"typeName\":\"iOS\",\"updateTime\":1788872652000,\"params\":{},\"createBy\":\"admin\",\"typePicType\":\"0\",\"createTime\":1641223870000,\"updateBy\":\"admin\",\"typePic\":\"\",\"typeId\":10,\"blogNum\":0,\"typePicLink\":\"\"},{\"typeName\":\"后端\",\"updateTime\":1788872613000,\"params\":{},\"createBy\":\"admin\",\"typePicType\":\"0\",\"createTime\":1641223889000,\"updateBy\":\"admin\",\"typePic\":\"\",\"typeId\":13,\"blogNum\":0,\"typePicLink\":\"\"}],\"blogPicType\":\"1\",\"updateTime\":1788873097685,\"params\":{},\"tags\":[{\"createBy\":\"admin\",\"createTime\":1641221405000,\"tagId\":20,\"updateBy\":\"admin\",\"updateTime\":1788872584000,\"params\":{},\"tagName\":\"PHP\",\"blogNum\":0},{\"createBy\":\"admin\",\"createTime\":1641223838000,\"tagId\":25,\"updateBy\":\"admin\",\"updateTime\":1788872532000,\"params\":{},\"tagName\":\"java\",\"blogNum\":0}],\"blogPic\":\"/profile/upload/2026/09/08/169b1cdb-0aaa-450b-8435-382488a81cf2.jpg\",\"createBy\":\"admin\",\"createTime\":1641097526000,\"typeIds\":[10,13],\"status\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-09-06 21:11:37');
INSERT INTO `sys_oper_log` VALUES (216, '文章管理', 2, 'com.ruoyi.cms.blog.controller.CmsBlogController.edit()', 'PUT', 1, 'admin', NULL, '/cms/blog', '127.0.0.1', '内网IP', '{\"tagIds\":[23,25],\"title\":\"java入门教程\",\"type\":\"1\",\"content\":\"<p>程序员面试背八股，可以说是现在互联网开发岗招聘不可逆的形式了，其中最卷的当属Java！（网上动不动就是成千上百道的面试题总结）你要是都能啃下来，平时技术不是太差的话，面试基本上问题就不会太大。</p><p><br></p><p><br></p><p>这时候尴尬的现象就出现了：<strong>虽然八股文背的好并不能代表这个人有实际工作能力，但企业还是会坚持要用八股文来考察候选人。</strong> 其中最直接的原因就是国内的开发岗位供过于求，非常内卷，而八股文就是目前企业最高效的甄别候选人的方式。我们无法改变这一现状，所以只能改变自己，适应目前互联网背八股的现状。</p><p><br></p><p>作者：Java水解</p><p>链接：https://juejin.cn/post/7254171813118001209</p><p>来源：稀土掘金</p><p><br></p><h1 class=\\\"ql-align-center\\\"><br></h1>\",\"top\":\"1\",\"updateBy\":\"admin\",\"blogDesc\":\"置顶文章\",\"id\":7,\"contentType\":\"1\",\"views\":80,\"blogFiles\":\"[]\",\"blogPicLink\":\"\",\"types\":[{\"typeName\":\"iOS\",\"updateTime\":1788872652000,\"params\":{},\"createBy\":\"admin\",\"typePicType\":\"0\",\"createTime\":1641223870000,\"updateBy\":\"admin\",\"typePic\":\"\",\"typeId\":10,\"blogNum\":0,\"typePicLink\":\"\"},{\"typeName\":\"后端\",\"updateTime\":1788872613000,\"params\":{},\"createBy\":\"admin\",\"typePicType\":\"0\",\"createTime\":1641223889000,\"updateBy\":\"admin\",\"typePic\":\"\",\"typeId\":13,\"blogNum\":0,\"typePicLink\":\"\"}],\"blogPicType\":\"1\",\"updateTime\":1788873214451,\"params\":{},\"tags\":[{\"createBy\":\"admin\",\"createTime\":1641223828000,\"tagId\":23,\"updateBy\":\"admin\",\"updateTime\":1788872557000,\"params\":{},\"tagName\":\"AI\",\"blogNum\":0},{\"createBy\":\"admin\",\"createTime\":1641223838000,\"tagId\":25,\"updateBy\":\"admin\",\"updateTime\":1788872532000,\"params\":{},\"tagName\":\"java\",\"blogNum\":0}],\"blogPic\":\"/profile/upload/2026/09/08/d4715c5d-c642-4c8a-bbef-228d5085ef30.jpg\",\"createBy\":\"admin\",\"createTime\":1641097526000,\"typeIds\":[10,13],\"status\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-09-06 21:13:34');
INSERT INTO `sys_oper_log` VALUES (217, '文章管理', 2, 'com.ruoyi.cms.blog.controller.CmsBlogController.edit()', 'PUT', 1, 'admin', NULL, '/cms/blog', '127.0.0.1', '内网IP', '{\"tagIds\":[20,21,22,23,24,25,26],\"title\":\"测试\",\"type\":\"1\",\"content\":\"<div data-inline-code-theme=\\\"red\\\" data-code-block-theme=\\\"tomorrow-night\\\"><div style=\\\"text-align:center;\\\" data-lines=\\\"3\\\" data-sign=\\\"d47c152f6d327c2e3a949c53bbc28008\\\" class=\\\"cherry-text-align cherry-text-align__center cherry-highlight-line\\\"><div class=\\\"cherry-panel--title\\\"></div><div class=\\\"cherry-panel--body\\\"><p><img alt=\\\"#141px #141px\\\" height=\\\"141px\\\" width=\\\"141px\\\" src=\\\"https://oscimg.oschina.net/oscnet/up-43e3941654fa3054c9684bf53d1b1d356a1.png\\\"></p></div></div><div data-lines=\\\"1\\\" data-type=\\\"div\\\" data-sign=\\\"1588c7b0360411b1de3ae10f4af6aa4a1\\\"><h1 style=\\\"margin: 30px 0 30px; font-weight: bold;\\\" align=\\\"center\\\">RuoYi v1.1.0</h1></div><div data-lines=\\\"2\\\" data-type=\\\"div\\\" data-sign=\\\"ecf0647da4d408316246fce04c598bd62\\\"><h4 align=\\\"center\\\">基于UniApp开发的轻量级移动端框架</h4></div><p data-lines=\\\"3\\\" data-type=\\\"br\\\" data-sign=\\\"br3\\\">&nbsp;</p><h2 data-lines=\\\"1\\\" data-sign=\\\"f9d3ebad82133323867ce4d3d1eefa3d\\\" id=\\\"%E5%B9%B3%E5%8F%B0%E7%AE%80%E4%BB%8B\\\"><a href=\\\"#%E5%B9%B3%E5%8F%B0%E7%AE%80%E4%BB%8B\\\" class=\\\"anchor\\\"></a>平台简介</h2><p data-lines=\\\"2\\\" data-type=\\\"br\\\" data-sign=\\\"br2\\\">&nbsp;</p><p data-lines=\\\"1\\\" data-type=\\\"p\\\" data-sign=\\\"9e31bb15d0a30eaeb402bce1e877fe811\\\">RuoYi App 移动解决方案，采用uniapp框架，一份代码多终端适配，同时支持APP、小程序、H5！实现了与<a href=\\\"https://gitee.com/y_project/RuoYi-Vue\\\">RuoYi-Vue</a>、<a href=\\\"https://gitee.com/y_project/RuoYi-Cloud\\\">RuoYi-Cloud</a>完美对接的移动解决方案！目前已经实现登录、我的、工作台、编辑资料、头像修改、密码修改、常见问题、关于我们等基础功能。</p><p data-lines=\\\"2\\\" data-type=\\\"br\\\" data-sign=\\\"br2\\\">&nbsp;</p><ul class=\\\"cherry-list__square\\\" data-sign=\\\"da719b1dc012190224df9406acc78d7a\\\" data-lines=\\\"9\\\"><li><p>配套后端代码仓库地址<a href=\\\"https://gitee.com/y_project/RuoYi-Vue\\\">RuoYi-Vue</a> 或 <a href=\\\"https://github.com/yangzongzhuan/RuoYi-Cloud\\\">RuoYi-Cloud</a> 版本。<br></p></li><li><p>应用框架基于<a href=\\\"https://uniapp.dcloud.net.cn/\\\">uniapp</a>，支持小程序、H5、Android和IOS。<br></p></li><li><p>前端组件采用<a href=\\\"https:/', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-09-06 21:14:20');
INSERT INTO `sys_oper_log` VALUES (218, '文章管理', 2, 'com.ruoyi.cms.blog.controller.CmsBlogController.edit()', 'PUT', 1, 'admin', NULL, '/cms/blog', '127.0.0.1', '内网IP', '{\"tagIds\":[26],\"title\":\"最新出品Java面试核心讲\",\"type\":\"1\",\"content\":\"<p>各种各样的编程语言不断崛起，但唯有Java是牢牢占据着老大的位置，目前几乎90%以上的大中型互联网应用系统在服务器端开发首选Java。</p><p>因此，也是吸引了不少年轻人投入到Java的学习之中。</p><p><br></p><p>所以，今天就跟大家分享一套系统的Java零基础入门学习教程，为小白量身定制。</p><p><br></p><p><br></p><p><a href=\\\"https://link.juejin.cn?target=https%3A%2F%2Fwww.bilibili.com%2Fvideo%2FBV1Rx411876f\\\" rel=\\\"noopener noreferrer\\\" target=\\\"_blank\\\"><strong>零基础也可以无压力的走进Java，学习Java！</strong></a></p><p><br></p><p><br></p><p>这套教程适用于没有任何Java基础，或者基础薄弱的小伙伴，它通俗易懂，并且非常全面，自发布以来，已破千万播放量，深受大家的好评。</p><p><br></p><p><br></p><p>教程讲解中更注重与学生互动，幽默风趣、细致入微，涵盖JavaSE所有核心内容，深入Java虚拟机，深度剖析源码，以代码实战贯穿始终，以项目驱动教学，将独特的PDT教学法展现的淋漓尽致。</p><p><br></p><p>作者：凌小可可</p><p>链接：https://juejin.cn/post/6989869446307250190</p><p>来源：稀土掘金</p><p>著作权归作者所有。商业转载请联系作者获得授权，非商业转载请注明出处。</p>\",\"top\":\"1\",\"updateBy\":\"admin\",\"blogDesc\":\"Java并发知识\",\"id\":19,\"contentType\":\"1\",\"views\":210,\"blogPicLink\":\"\",\"types\":[{\"typeName\":\"综合\",\"updateTime\":1788872685000,\"params\":{},\"createBy\":\"若依\",\"typePicType\":\"0\",\"createTime\":1641277883000,\"updateBy\":\"admin\",\"typePic\":\"\",\"typeId\":14,\"blogNum\":0,\"typePicLink\":\"\"}],\"blogPicType\":\"0\",\"updateTime\":1788873325350,\"params\":{},\"tags\":[{\"createBy\":\"若依\",\"createTime\":1641278906000,\"tagId\":26,\"updateBy\":\"\",\"params\":{},\"tagName\":\"若依\",\"blogNum\":0}],\"blogPic\":\"\",\"createBy\":\"admin\",\"createTime\":1641980454000,\"typeIds\":[14],\"status\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-09-06 21:15:25');
INSERT INTO `sys_oper_log` VALUES (219, '文章管理', 2, 'com.ruoyi.cms.blog.controller.CmsBlogController.edit()', 'PUT', 1, 'admin', NULL, '/cms/blog', '127.0.0.1', '内网IP', '{\"tagIds\":[21,25],\"title\":\"测试文字长度-一个简单的标题~标题就是要长才好玩=够长了\",\"type\":\"1\",\"content\":\"<h2>此事阿萨的</h2><h3>啊手动阀</h3><p><em>啊</em><em style=\\\"color: rgb(230, 0, 0);\\\">发生</em><em>的</em></p><p><s>奥迪发</s></p><p><span style=\\\"background-color: rgb(255, 255, 0);\\\">是否</span></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><h2 class=\\\"ql-align-center\\\"><strong>奥迪</strong></h2><p><u>啊手动阀</u></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><blockquote>var a = 1;</blockquote><blockquote>for (let i = 0; i &lt;10; i++){</blockquote><blockquote>}</blockquote><pre class=\\\"ql-syntax\\\" spellcheck=\\\"false\\\">var a = 1;\\nfor (let i = 0; i &lt;10; i++){\\n}\\n</pre><p>123</p><p><br></p><p><a href=\\\"http://www.baidu.com\\\" rel=\\\"noopener noreferrer\\\" target=\\\"_blank\\\">百度</a></p>\",\"top\":\"1\",\"updateBy\":\"admin\",\"blogDesc\":\"特殊字符测试\",\"id\":16,\"contentType\":\"1\",\"views\":148,\"blogPicLink\":\"\",\"types\":[{\"typeName\":\"Android\",\"updateTime\":1788872635000,\"params\":{},\"createBy\":\"admin\",\"typePicType\":\"0\",\"createTime\":1641223880000,\"updateBy\":\"admin\",\"typePic\":\"\",\"typeId\":11,\"blogNum\":0,\"typePicLink\":\"\"}],\"blogPicType\":\"0\",\"updateTime\":1788873455813,\"params\":{},\"tags\":[{\"createBy\":\"admin\",\"createTime\":1641221423000,\"tagId\":21,\"updateBy\":\"admin\",\"updateTime\":1788872570000,\"params\":{},\"tagName\":\"数据库\",\"blogNum\":0},{\"createBy\":\"admin\",\"createTime\":1641223838000,\"tagId\":25,\"updateBy\":\"admin\",\"updateTime\":1788872532000,\"params\":{},\"tagName\":\"java\",\"blogNum\":0}],\"blogPic\":\"\",\"createBy\":\"admin\",\"createTime\":1641347093000,\"typeIds\":[11],\"status\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-09-06 21:17:35');
