INSERT INTO `sys_oper_log` VALUES (229, '个人信息', 2, 'com.ruoyi.web.controller.system.SysProfileController.updateProfile()', 'PUT', 1, 'admin', NULL, '/system/user/profile', '127.0.0.1', '内网IP', '{\"roles\":[{\"flag\":false,\"roleId\":1,\"admin\":true,\"dataScope\":\"1\",\"params\":{},\"roleSort\":\"1\",\"deptCheckStrictly\":false,\"menuCheckStrictly\":false,\"roleKey\":\"admin\",\"roleName\":\"超级管理员\",\"status\":\"0\"}],\"phonenumber\":\"15877777888\",\"admin\":true,\"loginDate\":1788871374000,\"remark\":\"管理员\",\"delFlag\":\"0\",\"loginIp\":\"127.0.0.1\",\"email\":\"ry@163.com\",\"nickName\":\"admin\",\"sex\":\"0\",\"deptId\":103,\"avatar\":\"/profile/avatar/2026/09/08/817e7571-8c6a-4c35-bdd8-0cc703baea2f.jpeg\",\"dept\":{\"deptName\":\"研发部门\",\"leader\":\"若依\",\"deptId\":103,\"orderNum\":\"1\",\"params\":{},\"parentId\":101,\"children\":[],\"status\":\"0\"},\"params\":{},\"userName\":\"admin\",\"userId\":1,\"createBy\":\"admin\",\"createTime\":1639116734000,\"status\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-09-06 22:32:27');
INSERT INTO `sys_oper_log` VALUES (230, '文章管理', 2, 'com.ruoyi.cms.blog.controller.CmsBlogController.edit()', 'PUT', 1, 'admin', NULL, '/cms/blog', '127.0.0.1', '内网IP', '{\"tagIds\":[],\"title\":\"写给程序员的思考书\",\"type\":\"2\",\"content\":\"<p>这本书的原名为《程序员的自我修养》，我不喜欢这个书名，口气过大，仿佛有意将自己的一些见解制定成衡量一名程序员习性的尺度。不过作为菜鸟，我依然带着学习的眼光去阅读它。</p><p><br></p><p>这本书的内容比较丰富，我在这里无法面面俱到，我以自身的角度出发，用设问的形式来总结一些书中的观点，以及标注一些我自己的看法。一是给予后进些许资料，二是时刻用来自勉。</p><p><br></p><p><br></p><h2>如何出类拔萃？</h2><p><br></p><p>或许这个问题依然比较宽泛，那我们不妨缩小范围，目光短浅一点，变成“如何在自身周围的圈子里出类拔萃？”</p><p><br></p><ul><li>作为开发者，首要的根本即是技术，这是一种自身能力的证明，获得尊重的最直接有效的途径。在我的接触中，技术能力出色的无疑是dalao，然而也存在一部分这样的同学：只谈概念，只谈上层建筑，形而上，虚无缥缈如入化境。我内心是十分鄙夷的，仿佛回想起孔乙己对人说话总是满口之乎者也，叫人半懂不懂的。写到这里，来了兴味，小试牛刀，跑了题了。</li></ul><blockquote><br></blockquote><blockquote>孔乙己一到公司，所有敲代码的人便都看着他笑，有的叫道，“孔乙己，你提交的代码又出新BUG了！”他不回答，对前台说，“换两块CPU，加一根内存条。”他们又故意高声嚷道，“你一定又用了人家的库了！”孔乙己睁大眼睛说，“你怎么这样凭空污人清白.....”“什么清白？我前天亲眼见你在Github上clone，还不给star。”孔乙己便涨红了脸，额上的青筋条条绽出，争辩道，“开源不能算偷.....开源！......开发者的事，能算偷吗？”接连便是难懂的话，什么“大数据”、“云计算”，什么“深度学习”之类，引得众人都哄笑起来：公司内外充满了快活的pm2.5。</blockquote><p><br></p><ul><li>完善技能树。读一些与技术无关的人文类、经济类的书；能写一个格式工整，思路清晰的文档；能做一套界面简洁，内容丰富的PPT；能简明利落地表达自己的想法等等小技能。</li></ul><p><br></p><blockquote><br></blockquote><blockquote>“我曾经接触过一些IT高管及行业的技术大牛，当私下聊起他们是如何变得如此出类拔萃时，他们大多会以自嘲但又略带得意的语气来讲述他们的那些独门秘籍。</blockquote><blockquote><em>我的文档写得特别好。</em></blockquote><blockquote><em>我写过几篇很受欢迎的文章。</em></blockquote><blockquote><em>我热爱开源文化，并在社区里很有名。</em>”</blockquote><blockquote><br></blockquote><p><br></p><ul><li>建立良好的社交联系，与身边的同伴沟通，与网络社区中的人交流。</li></ul><p><br></p><p><br></p><h2>是否该留在一线城市？</h2><p><br></p><ul><li>这个问题我觉得属于老生常谈了，没有标准答案，因为每个人的心理预期和人生规划都是有差异的。（等于没说）最主要的还是房子产生的一系列复杂的问题。下面就“是否该留在一线城市”从两个方面各谈谈优点吧（缺点就是相互取反）</li></ul><p><br></p><p><br></p><blockquote><br></blockquote><blockquote>留在一线城市，有最好的资源。无论硬件还是软件，一线城市汇聚了最完备的基础设施和最优秀的人才。这里有最适合程序员成长的环境和氛围，无论是软件园还是创业园，总是充满着机会和挑战，在这里你更容易获得广阔的视野和出色的伙伴。当然你未来的家庭、子女也都能够享受到这样的资源。还有一点不得不提的是，一旦离开，将很难再回来。</blockquote><p><br></p><blockquote><br></blockquote><blockquote>房价的上涨让很多方得到了好处，国家的GDP得到了保障，地方政府的债务得到了缓解，投机客成了首批实现财务自由的群体。更多人成为了房奴，社会上出现了隐性的阶级：有房阶级与无房阶级。在一线城市买房本身并不会给你带来持久的快乐，因为当你买完房后，你会欠一大笔债，需要几十年才能还清；当你终于把欠款还清时，你又会觉得这套房子太小，已经不够一家人住，需要换一套更大的房子。</blockquote><', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-09-06 11:20:35');
